shell_commands:
cd /tmp/ajv-probe && cat > default.mjs <<'EOF'
import Ajv from 'ajv';
console.log('default import: typeof =', typeof Ajv, '| .Ajv =', typeof Ajv?.Ajv, '| .default =', typeof Ajv?.default);
try {
  const v = new Ajv({strict: false, validateFormats: false, allErrors: true}).compile({type:'object', required:['x']});
  console.log('new Ajv() OK, validate({}) =', v({}));
} catch (e) { console.log('new Ajv() FAILED:', e.message); }
EOF
cat > named.mjs <<'EOF'
import {Ajv} from 'ajv';
console.log('named import typeof =', typeof Ajv);
EOF
node default.mjs; node named.mjs 2>&1 | tail -3

cd /tmp/ajv-probe && cat > inspect.mjs <<'EOF'
import mod from 'ajv';
const ns = await import('ajv');
const cjs = (await import('node:module')).createRequire(import.meta.url)('ajv');
console.log('ns keys:', Object.keys(ns).join(','));
console.log('mod === ns.default:', mod === ns.default);
console.log('require("ajv") typeof:', typeof cjs, '| is ns.default:', cjs === ns.default);
console.log('mod has .default:', 'default' in (mod ?? {}), '| mod.Ajv === mod:', mod?.Ajv === mod);
EOF
node inspect.mjs

cd /tmp/ajv-probe && cat > msgs.mjs <<'EOF'
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const fmt = v => (v.errors ?? []).map(e => `${e.instancePath || 'input'} ${e.message}`).join('; ');
const v1 = ajv.compile({type:'object', properties:{location:{type:'string'}}, required:['location']});
console.log('missing:', `Tool input rejected: ${fmt(v1)}`.replace.bind(fmt(v1)) === null ? '' : `Tool input rejected: ${fmt(v1)}`);
const v2 = ajv.compile({type:'object', properties:{ssn:{type:'string'}}, required:['ssn']});
v2({ssn: 123456789});
console.log('wrongtype:', fmt(v2));
console.log('leaks value?', fmt(v2).includes('123456789'));
EOF
node msgs.mjs

cd /tmp/ajv-probe && cat > msgs2.mjs <<'EOF'
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
const fmt = v => (v.errors ?? []).map(e => `${e.instancePath || 'input'} ${e.message}`).join('; ');
const v1 = ajv.compile({type:'object', properties:{location:{type:'string'}}, required:['location']});
v1({});
const result = `Tool input rejected: ${fmt(v1)}`;
console.log('missing:', result);
console.log('has location:', result.includes('location'), '| has required:', /required/i.test(result));
const v2 = ajv.compile({type:'object', properties:{n:{type:'string', enum:['a','b']}, x:{type:'number'}}, required:['n','x']});
v2({n:'c', x:'nope', extra:1});
console.log('multi:', fmt(v2));
EOF
node msgs2.mjs
